// Stands in for the GitHub Copilot SDK under tests/test_chat_bridges.py: a client whose session
// records how it was used in $FAKE_LOG (one JSON line each) and answers every send with the events
// in $FAKE_SCRIPT, as the real one relays the Copilot runtime's. An entry {"ask": request} consults
// the bridge's onUserInputRequest and reports the answer as an assistant message.
import { appendFileSync, readFileSync } from 'node:fs';

const log = entry => appendFileSync(process.env.FAKE_LOG, JSON.stringify(entry) + '\n');

export const approveAll = () => ({ kind: 'approved' });
export const RuntimeConnection = { forStdio: options => ({ kind: 'stdio', ...options }) };

class Session {
  constructor(config) { this.config = config; }
  rpc = {
    commands: {
      list: async () => ({ commands: [{ name: 'compact', description: 'Summarise', input: { hint: 'focus' } }] }),
      invoke: async request => (log({ invoke: request }),
        request.name === 'compact' ? { kind: 'completed', message: 'Compacted.' } : { kind: 'text', text: 'usage', markdown: false }),
    },
    model: { getCurrent: async () => ({ modelId: 'gpt-test' }), setReasoningEffort: async request => log({ effort: request }) },
    plan: { readSqlTodos: async () => ({ rows: [{ title: 'First', status: 'done' }, { title: 'Second', status: 'in_progress' }] }) },
  };
  async getEvents() { return JSON.parse(process.env.FAKE_HISTORY || '[]'); }
  async send(options) {
    log({ send: options });
    (async () => {
      for (const event of JSON.parse(readFileSync(process.env.FAKE_SCRIPT, 'utf8'))) {
        if (!event.ask) { this.config.onEvent(event); continue; }
        const answer = await this.config.onUserInputRequest(event.ask, { sessionId: 's' });
        this.config.onEvent({ type: 'assistant.message', data: { messageId: 'answered', content: JSON.stringify(answer) } });
      }
      this.config.onEvent({ type: 'session.idle', data: {} });
    })();
    return 'm1';
  }
  async abort() { log({ abort: true }); }
  async setModel(id) { log({ model: id }); }
  async disconnect() {}
}

export class CopilotClient {
  constructor(options) { log({ client: options }); }
  async start() {}
  async stop() { return []; }
  async getStatus() { return { version: '4.5.6' }; }
  async listModels() { return [{ id: 'gpt-test', name: 'GPT Test', billing: { multiplier: 1 }, supportedReasoningEfforts: ['low', 'high'], defaultReasoningEffort: 'low' }]; }
  async createSession(config) {
    log({ create: { ...config, onEvent: typeof config.onEvent, onPermissionRequest: config.onPermissionRequest === approveAll,
                    onUserInputRequest: typeof config.onUserInputRequest, onExitPlanModeRequest: typeof config.onExitPlanModeRequest } });
    return new Session(config);
  }
  async resumeSession(id, config) {
    log({ resume: id });
    if (!process.env.FAKE_HISTORY) throw new Error('no such session');
    return new Session(config);
  }
}
